sources=[{'id':'openrb','url':'https://emanual.robotis.com/docs/en/parts/controller/openrb-150/','fact':'Four DXL ports share a 3 A rating. USB input has a 500 mA fuse; this is not a 3 A motor-current limiter.'},{'id':'schematic','url':'https://emanual.robotis.com/docs/en/parts/controller/openrb-150/#download','local':str(W/'sources/openrb-150-schematic-20231130.pdf'),'fact':'Inspected actual archived schematic: JP1 selects J4 terminal power or diode-fed USB/VIN. The terminal position separates MAIN_VCC from USB VBUS/D3. J4 GND remains common.'},{'id':'xl330','url':'https://emanual.robotis.com/docs/en/dxl/x/xl330-m288/','fact':'3.7–6 V, recommended 5 V. 1.47 A specified 5 V stall; 17 mA standby. Address 38 current limit applies to current/current-based-position modes. XL330 measures input supply current, not generic X-series phase current.'},{'id':'eh','url':'https://www.jst-mfg.com/product/pdf/eng/eEH.pdf','fact':'EH rated 3 A with AWG22. This does not rate a whole chained group for five simultaneous stalls.'},{'id':'dfr','url':'https://www.dfrobot.com/product-2907.html','fact':'6–24 V input, 5 V ±1%, 16 A maximum; output-short and 125°C over-temperature protection. Trip curve not published.'},{'id':'pd','url':'https://learn.adafruit.com/adafruit-usb-type-c-power-delivery-switchable-breakout','fact':'5991 HUSB238 voltage request depends on the source contract; verify actual 20 V before connecting the 6 V minimum-input converter.'}]
