frozen=['ttl-05-04','ttl-04-03','ttl-03-02','ttl-02-01','ttl-10-09','ttl-09-08','ttl-08-07','ttl-07-06']
steps=[
{'id':'power-01','title':'Prepare the external source','prepare':['Keep the robot disconnected. Use the existing MDY-14-ED and its original unmodified cable.','Set only the 20 V request on the existing 5991; its board stays outside the robot.'], 'assemble':['Connect the 2 m paired 18 AWG tether via the existing XT30 interface; use recessed live contacts on the source side.','Route both tether conductors together. Anchor the jacket before any solder joint.'], 'check':['Measure the negotiated voltage and polarity at the robot end before connecting DFR1202. A 5 V fallback is below its 6 V input requirement.','The 120 W charger label is not the active USB-PD contract; the existing design target is 20 V / 3.25 A.']},
{'id':'power-02','title':'Prepare the converter and two distribution joints','prepare':['Remove power; leave both torso covers off and the converter outside its carrier.','Prepare one 16 AWG lead per VOUT and GND land. Do not pile all outgoing branches on the small PCB land.'], 'assemble':['Solder the red lead to VOUT and black lead to GND on the exposed rear lands. Follow the registered pad image, not the shape of the PCB box.','Make the two branch splices on the bench. Mechanically interlock the stripped conductors, solder with complete wetting, and support the insulated wire beyond the solder-wicked section. Slide heat-shrink on before closing the joint.','Insulate the positive and return splices separately. Their finished receiving size is at most 6 mm diameter × 12 mm length in this candidate; no finished connector is assumed purchased.'], 'check':['Inspect for loose strands, bridges, incomplete wetting, exposed conductor, and strain transferred to the pad. Perform a pull check and unpowered continuity/short check.','A real joint that exceeds the receiving size needs rearrangement before closing the cover; the envelope alone does not certify workmanship.']},
{'id':'power-03','title':'Place the body-side harness','prepare':['Use the original body width, hip spacing and DFR carrier. Retain the accepted IMU board, cover and four local leads.'], 'assemble':['Install the prewired DFR board in the original battery bay. Its PCB rear datum is X = −31.5 mm; components face −X.','Take both output leads through the existing negative-Y bracket opening. Only after clearing that bracket, fan the return to +Y.','Place the insulated positive and return joints above the support at centers [−7,−7,35.5] and [−7,+7,35.5] mm, length direction X. Secure insulated sections to existing support features; keep ties off soldered and flexing sections.'], 'check':['Do not trap wire under the roof edge or bracket hook. The local route was checked against the original body, all four IMU leads and both IMU covers.','Modeled pad-to-joint conductor lengths are 68.134 mm positive and 72.749 mm return. These are installed centerline lengths, not a cut-to-length instruction; leave assembly/termination allowance and trim after fitting.']},
{'id':'power-04','title':'Separate motor power into three zones','prepare':['Keep the eight accepted leg-to-leg cables intact, with all three contacts.','Identify incoming routes OpenRB→15, OpenRB→10 and 12→5 by motor ID; verify pin numbering from the keyed housing.'], 'assemble':['On each zone boundary, carry DATA on pin 3 only across the boundary. Isolate source-side pin 2 (VDD) and pin 1 (GND); retain removed terminals reversibly and individually insulate them.','At the receiving motor end, connect pin 2 to that zone’s dedicated 5 V feed and pin 1 to its dedicated return. The data conductor remains continuous. Common ground is established by the paired power returns at the distribution joint, never left floating.','Route the data lead beside its corresponding ground-return path. Do not add a long isolated data loop or reconnect a motor return through OpenRB/USB.'], 'check':['With power removed, confirm three VDD islands: IDs 1–5, 6–10, and 11–15. No island may have continuity to OpenRB DXL VDD.','Confirm all returns share the designated distribution ground; check that cross-zone pin 1 cannot become a parallel motor-current return.','This is a power-interface change at the three incoming lines; it does not alter the eight frozen leg routes.']},
{'id':'power-05','title':'Supply the head electronics','prepare':['Leave the head open. Keep Pi→OpenRB USB as a complete data connection; do not substitute a Mac cable or remove VBUS from a cable without a device-detection design.'], 'assemble':['Give OpenRB J4 its own paired 5 V/GND supply. Set JP1 to VIN(DXL), the terminal-power position, before plugging USB. Do not use the accessory 5 V pin to power Pi.','Feed Pi Zero W using two 22 AWG 5 V leads to physical pins 2 and 4, and two matched ground leads to pins 6 and 14. Keep Pi PWR IN USB empty.','Give MAX98357A VIN/GND a separate paired branch. Keep speaker +/− on the amplifier output only; neither speaker terminal is a ground connection.','Camera receives power through CSI. BNO085 remains on Pi 3.3 V/I2C: physical pins 1 (3.3 V), 3 (SDA), 5 (SCL), 9 (GND).'], 'check':['Verify the OpenRB jumper position against the official board graphic. The inspected schematic separates USB VBUS from MAIN_VCC in this terminal position.','Do not apply 20 V to OpenRB, Pi, the amplifier, camera or any motor.','Head endpoints and moving-neck service loops remain tied to the final adopted head layout; a schematic is not a completed physical cable route.']},
{'id':'power-06','title':'Check before closing and before loading','prepare':['Keep the torso and head open for the first continuity inspection. Support the robot with motors initially torque-disabled.'], 'assemble':['After the unpowered tests, commission one zone at a time. Read back motor IDs, operating mode, voltage and current limits before enabling torque.','The initial engineering setting is 450 mA per motor in a supported current/current-based-position mode: 2.25 A per five-motor zone, 6.75 A motor total. It requires runtime integration; a position-only mode must not silently inherit this claim.','Retain the existing 9 A continuous / 9.5 A short-peak whole-robot budget and a 2 A nonmotor reserve. Do not increase the existing runtime stop threshold without measurement.'], 'check':['Measure each zone’s startup and representative motion current, connector temperature and remote voltage. Keep every shared EH path below its 3 A rating.','Five simultaneous nominal stalls are 7.35 A per zone and 22.05 A for all motors; that is outside this design envelope, not a forecast of normal walking current.','Verify full joint travel with slack, strain relief and covers open, then close while watching every wire crossing. Digital body fit does not certify the head harness, powered robot or solder quality.']}
]
lineSpec=[{'id':'external-tether','from':'5991 selected 20 V / GND','to':'DFR VIN / distribution GND','gaugeAWG':18,'installedLengthMm':2000,'lengthEvidence':'Existing design contract; physical termination allowances additional','physicalRouteAccepted':False}, {'id':'converter-positive','from':'DFR VOUT rear land','to':'5 V distribution splice','gaugeAWG':16,'installedLengthMm':sum(p['lengthMm'] for p in feeds['parts'] if p['net']=='5V'),'physicalRouteAccepted':True},{'id':'converter-return','from':'DFR GND rear land','to':'return distribution splice','gaugeAWG':16,'installedLengthMm':sum(p['lengthMm'] for p in feeds['parts'] if p['net']=='GND'),'physicalRouteAccepted':True}]
