report={'schemaVersion':1,'problemIds':['P5','P6'],'date':'2026-10-09','status':'THREE_ZONE_DESIGN_WITH_CHECKED_BODY_DISTRIBUTION;_HEAD_AND_ZONE_FEEDS_PENDING','newExternalFuseCount':0,'wholeHarnessAccepted':False,'physicalCommissioningPassed':False,'source':{'charger':'existing MDY-14-ED','receiver':'existing Adafruit5991 external','targetPD':[20,3.25],'converter':'existing DFR1202 in original battery bay','sourceContractPhysicallyMeasured':False},'powerGroups':groups,'unchangedThreeConductorLegRoutes':frozen,'crossZoneContactPolicy':{'pin1':'Source end isolated; receiving side dedicated zone return','pin2':'Source end isolated; receiving side dedicated zone 5 V','pin3':'DATA continuous','groundReference':'Dedicated paired power returns meet at one designated distribution node; data is not floating'},'openrbPower':{'input':'J4 terminal5V/GND','jumper':'VIN(DXL), JP1 terminal position','dxlMotorPowerCurrentA':0,'usbDataTopology':'Pi host → OpenRB device, full USB retained','USBBackfeedBasis':'Actual schematic JP1 terminal position disconnects MAIN_VCC from diode-fed USB VBUS branch','boardPowerAndUSBPhysicalTestPassed':False},'budgets':{'continuousRobotA':9,'shortPeakRobotA':9.5,'nonmotorReserveA':2,'initialMotorInputLimitA':.45,'initialMotorTotalA':6.75,'initialZoneTotalA':2.25,'ehRatedA':3,'currentLimitModeRequirement':'Current control or current-based position control; read back address38 before torque; not a physical short-circuit protector','allMotorStallStressA':22.05,'activeOvercurrentProtection':'Existing source/converter protections only; no added 11-fuse array, no assertion of selective branch fault protection'},'localGeometry':{'junctionPairs':326,'feedPairs':666,'crossPairs':8,'passed':True,'scope':'DFR output pads to insulated body splices only; receiving geometry, not completed outgoing branches','jointCentersMm':[[-7,-7,35.5],[-7,7,35.5]],'jointMaximumReceivingMm':{'diameter':6,'length':12},'noPrintedPartChange':True},'connections':lineSpec,'steps':steps,'sources':sources,'sourceHashes':hashes,'remainingEngineeringWork':['Incoming VIN/tether internal termination and strain relief','Zone injection adapter physical placement and actual cut lengths','Head branch endpoints and complete moving-neck slack with adopted head layout','Splice insulation, wire stock and powered representative-load commissioning'],'stockBoundary':'Wire, heat-shrink and termination consumables remain club-first/stock-unverified. No orders/cart changes or sourcing hold release.'}
(D/'integrated-harness.json').write_text(json.dumps(report,indent=2)+'\n')
