for p in feeds['parts']:parts.append(dict(p,color='#e85b44' if p['net']=='5V' else '#24272e',geometryKind='body-wire-routing-example'))
for p in j['parts']:parts.append(dict(p,color='#e85b44' if p['key'].endswith('5v') else '#24272e',geometryKind='insulated-splice-receiving',notPrintedPart=True))
manifest={'status':'LOCAL_BODY_DISTRIBUTION_ONLY','integrationReady':False,'integrationScope':'Replace only old DFR output corridor with these checked local feeds/splice receiving envelopes; do not promote incomplete external/zone/head routes','units':'mm','removedParts':['power_5v_pad_lead','power_5v_pad_connected','power_gnd_pad_lead','power_gnd_pad_connected'],'additionalParts':parts,'receipt':str(D/'integrated-harness.json'),'receiptSha256':sha(D/'integrated-harness.json'),'wholeHarnessAccepted':False,'printChanges':[],'supersededLegacyPowerParts':['fuse_carrier']+['nut_E-fuse_carrier-%02d'%i for i in range(1,5)],'supersededLegacyPowerScrews':['E-fuse_carrier-%02d'%i for i in range(1,5)],'supersededLegacyOperations':['power-03','power-04'],'supersessionScope':'Remove the withdrawn added fuse carrier and its four nuts/screws; replace legacy population/fastening instructions with the three-zone tutorial. Retain converter, original carrier/support, original body geometry and held procurement state.'}
